from __future__ import annotations

import logging

import pytest

from sundgren.core.junit import parse_junit
from support import FIXTURES

JUNIT = FIXTURES / "junit"


def suite(*cases: str) -> str:
    return f'<testsuite name="s">{"".join(cases)}</testsuite>'


def test_pytest_fixture() -> None:
    # Generated by pytest 9.1.1 with --junitxml and --continue-on-collection-errors; hostname,
    # timestamp and absolute paths neutralised by hand.
    got = parse_junit((JUNIT / "pytest.xml").read_text(encoding="utf-8"))
    mod = "tests.test_outcomes"
    assert got == {
        "tests.test_broken_import": "error",  # collection error, empty classname
        f"{mod}.TestCalc::test_method": "passed",
        f"{mod}.TestCalc::test_method_fail": "failed",
        f"{mod}.TestOuter.TestInner::test_nested": "passed",
        f"{mod}::test_fail": "failed",
        f"{mod}::test_fail_and_teardown_error": "error",  # two testcases: failure, then error
        f"{mod}::test_param[-1-neg]": "passed",
        f"{mod}::test_param[0-zero]": "passed",
        f"{mod}::test_param[5-pos]": "passed",
        f"{mod}::test_pass": "passed",
        f"{mod}::test_setup_error": "error",
        f"{mod}::test_skip": "skipped",
        f"{mod}::test_skip_imperative": "skipped",
        f"{mod}::test_teardown_error": "error",
        f"{mod}::test_xfail": "xfailed",
        f"{mod}::test_xfail_imperative": "xfailed",
        f"{mod}::test_xpass_nonstrict": "passed",  # indistinguishable from a pass
        f"{mod}::test_xpass_strict": "xpassed",
    }
    assert list(got) == sorted(got)


def test_nextest_fixture() -> None:
    got = parse_junit((JUNIT / "nextest.xml").read_text(encoding="utf-8"))
    assert got == {
        "shed-rs::calc_it::classify_negative": "passed",  # <flakyFailure> only: passed on retry
        "shed-rs::tests::test_add": "passed",
        "shed-rs::tests::test_classify": "skipped",
        "shed-rs::tests::test_divide": "failed",
    }


def test_root_testsuite_and_classname_fallback() -> None:
    xml = suite(
        '<testcase classname="pkg.mod" name="t1"/>',
        '<testcase classname="" name="t2"/>',
        '<testcase name="t3"/>',
    )
    assert parse_junit(xml) == {"pkg.mod::t1": "passed", "t2": "passed", "t3": "passed"}


def test_nested_suites() -> None:
    inner = suite('<testcase classname="b" name="t2"><failure/></testcase>')
    outer = f'<testsuite name="outer"><testcase classname="a" name="t1"/>{inner}</testsuite>'
    xml = f"<testsuites>{outer}</testsuites>"
    assert parse_junit(xml) == {"a::t1": "passed", "b::t2": "failed"}


@pytest.mark.parametrize(
    ("child", "outcome"),
    [
        ('<failure message="boom"/>', "failed"),
        ("<error/>", "error"),
        ('<skipped message="no"/>', "skipped"),
        ("<skipped/>", "skipped"),
        ('<skipped type="pytest.xfail" message="known bug"/>', "xfailed"),
        ('<skipped type="pytest.skip" message="xfails on windows"/>', "skipped"),
        ('<skipped message="xfail: reason"/>', "xfailed"),
        ('<skipped message="xfail-marked test passes unexpectedly"/>', "xpassed"),
        ('<failure message="[XPASS(strict)] must fail"/>', "xpassed"),
        ("<system-out>log</system-out><properties/>", "passed"),
        ("<rerunFailure/><rerunFailure/>", "passed"),
        ('<skipped message="x"/><error message="teardown"/>', "error"),
    ],
)
def test_outcome_mapping(child: str, outcome: str) -> None:
    assert parse_junit(suite(f'<testcase classname="c" name="t">{child}</testcase>')) == {
        "c::t": outcome
    }


@pytest.mark.parametrize(
    ("first", "second", "outcome"),
    [
        ("", "<error/>", "error"),
        ("<error/>", "", "error"),
        ("<failure/>", "<error/>", "error"),
        ("<failure/>", "", "failed"),
        ("", "<skipped/>", "skipped"),
        ("<skipped/>", '<skipped type="pytest.xfail"/>', "xfailed"),
    ],
)
def test_duplicate_id_resolves_to_most_severe(first: str, second: str, outcome: str) -> None:
    xml = suite(
        f'<testcase classname="c" name="t">{first}</testcase>',
        f'<testcase classname="c" name="t">{second}</testcase>',
    )
    assert parse_junit(xml) == {"c::t": outcome}


def test_empty_report() -> None:
    assert parse_junit('<?xml version="1.0" encoding="utf-8"?><testsuites/>') == {}


def test_leading_bom_is_accepted() -> None:
    assert parse_junit('\ufeff<?xml version="1.0"?>' + suite('<testcase name="t"/>')) == {
        "t": "passed"
    }


def test_testcase_without_name_is_skipped(caplog: pytest.LogCaptureFixture) -> None:
    xml = suite(
        "<testcase classname='c'><failure/></testcase>",
        "<testcase classname='c' name=''/>",
        "<testcase classname='c' name='t'/>",
    )
    with caplog.at_level(logging.DEBUG, logger="sundgren.core.junit"):
        assert parse_junit(xml) == {"c::t": "passed"}
    assert len(caplog.records) == 2


@pytest.mark.parametrize(
    "text",
    [
        "",
        "<testsuite><testcase name='t'>",
        "not xml at all",
        "<coverage/>",
        suite("<testcase name='t\0'/>"),
    ],
)
def test_invalid_input_raises_value_error(text: str) -> None:
    with pytest.raises(ValueError):
        parse_junit(text)
